syntax:
scope_resolution ::= '::' identifier
// Used to access members of a namespace or class, or to specify global scope
// Example: NamespaceName::MemberName or ClassName::MemberName

code_example:
#include <iostream>
namespace M {
    namespace N {
        class X {
        public:
            static int i;
            void f();
        };
        class B {
        public:
            static int i;
        };
        int X::i = 10;
        int B::i = 5;
        void X::f() {
            // Local variable 'i' is not declared here
            // Accessing 'i' through scope resolution
            std::cout << "Global i: " << ::i << std::endl;
            std::cout << "M::N::X::i: " << X::i << std::endl;
            std::cout << "M::N::B::i: " << B::i << std::endl;
        }
        int i = 42; // Global variable in namespace M::N
    }
    int i = 100; // Global variable in namespace M
}
int i = 200; // Global variable in global scope
int main() {
    M::N::X obj;
    obj.f();
    return 0;
}
